let ui = { productSearch:'', productCategory:'all', posSearch:'', invoiceSearch:'', cart:[], bulkType:'products', bulkRows:[], bulkText:'', selectedCustomer:'c1', mobileNav:false, barcodeProduct:'', barcodeQueue:[], barcodeSize:'50x25', barcodeMode:'roll', barcodeShowName:true, barcodeShowSku:true, barcodeShowPrice:true, barcodeShowBrand:false, barcodeShowModel:false, barcodeShowCategory:false, barcodeShowSpec:false, barcodeShowUom:false, barcodeShowRack:false, barcodeShowText:true, barcodePriceType:'retail', barcodeCustomPrice:'', barcodeCustomText:'', barcodeCustomText2:'', barcodeCopies:1, barcodeFormat:'CODE128', barcodeGap:2, barcodePadding:1.2 };
const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const esc = v => String(v ?? '').replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[c]));
const tenantId = () => state.currentTenantId || 'tenant-demo';
const me = () => state.users.find(u => u.id === state.session?.userId);
const shop = () => state.shops.find(s => s.id === tenantId()) || state.shops[0];
const tenantData = key => (state[key] || []).filter(x => x.tenantId === tenantId());
const can = permission => {
  const user = me(); if (!user) return false;
  const p = permissionsByRole[user.role] || [];
  return p.includes('*') || p.includes(permission);
};

